import { useQuery, type UseQueryOptions } from "@tanstack/react-query";
import { getQuiz } from "../handlers/getQuiz";
import type { ApiError } from "../runtime/client";
import type { SpacePartition } from "../types/SpacePartition";
import type { SpaceQuizEntityType } from "../types/SpaceQuizEntityType";

type Data = Awaited<ReturnType<typeof getQuiz>>;

export function useGetQuiz(
  spacePk: SpacePartition,
  quizId: SpaceQuizEntityType,
  options?: Omit<UseQueryOptions<Data, ApiError>, "queryKey" | "queryFn">,
) {
  return useQuery<Data, ApiError>({
    queryKey: ["getQuiz", spacePk, quizId],
    queryFn: () => getQuiz(spacePk, quizId),
    ...options,
  });
}
